/* ---- food add ---- */
var _FOODSHEET={q:'',local:[],branded:[],state:'idle',picked:null};
function openFoodAdd(day,pre){_FOODSHEET={q:'',local:[],branded:[],state:'idle',picked:pre||null};openSheet('edit',{form:'foodAdd',title:'Add food',desc:'Search, choose a portion, assign a meal. The nutrient snapshot and source version travel with the entry.',buf:{date:day||todayISO(),meal:'lunch',amount:1,unit:'serving'}});if(pre)prepPortion(pre);}
function prepPortion(f){normalizeFood(f);var b=_SHEET.buf;var opts=portionOptions(f);b.unit=opts[0].value;b.amount=1;if(f.lastQuantity!=null&&!f.portions.length){b.unit=f.lastBasis==='ml'?'ml':(f.lastBasis==='serving'?'serving':'g');b.amount=f.lastQuantity;}renderSheet();}
SHEETS.foodAdd=function(b){var F=_FOODSHEET;var body='';
  if(!F.picked){body+='<div class="form-row">'+(aiReady('meal').ok?'<div class="btn-row">'+uiBtn('Describe a meal instead','ai.meal',null,'btn-sm btn-ghost')+'</div>':'')+'<label for="fs_q">Search</label><div class="search-row"><input id="fs_q" type="search" value="'+attrEsc(F.q)+'" placeholder="name or barcode" data-act="foodsheet.search" data-ev="input" autocomplete="off"><button type="button" class="st-b" data-act="foodsheet.clear" aria-label="clear the search">\u2715</button></div>'+uiMicBtn('fs_q')+uiBtn('Scan barcode','food.scan',null,'btn-sm btn-secondary')+'</div><div id="fs_results">'+renderFoodSheetResults()+'</div>';}
  else{var f=normalizeFood(F.picked);var res=portionResolve(f,b.amount,b.unit);var n=res&&res.qty>0?nutrientsFor(f,res.qty):null;var mc=macroConsistency(f);var basisNote=f.basis==='ml'?'nutrients per 100 mL (label serving unit is mL); logged by volume or servings \u2014 grams are not invented':(f.basis==='serving'?'per-serving nutrients only (volume ingredients without a density)':'nutrients per 100 g');
    body+='<div class="card" style="padding:12px"><div class="card-title">'+esc(f.name)+(f.brand?' <span class="muted">'+esc(f.brand)+'</span>':'')+'</div><div class="prov">'+esc(f.source)+' '+esc(String(f.version||''))+(f.category?' \u00b7 '+esc(f.category):'')+(f.energySource&&f.energySource!=='label'?' \u00b7 energy '+esc(f.energySource):'')+(f.gtin?' \u00b7 GTIN '+esc(f.gtin):'')+' \u00b7 '+esc(basisNote)+(f.householdServing?' \u00b7 label serving '+esc(f.householdServing):'')+'</div>'+(mc&&mc.note?'<div class="hint warn">'+esc(mc.note)+'</div>':'')+'</div><div class="form-trio">'+fld('amount','Amount',{type:'number'})+fld('unit','Portion',{type:'select',options:portionOptions(f).map(function(o){return [o.value,o.label];})})+fld('meal','Meal',{type:'select',options:MEALS.map(function(m){return [m,m];})})+'</div>'+fld('date','Date',{type:'date'})+(n?'<div class="row"><div class="l">'+esc(res.label)+(res.approx?' <span class="muted">approximate</span>':'')+'</div><div class="r"><strong>'+(n.kcal!=null?fmtNum(n.kcal,0)+' kcal':'energy unknown')+'</strong><small>P '+fmtNum(n.protein,0)+' \u00b7 C '+fmtNum(n.carbs,0)+' \u00b7 F '+fmtNum(n.fat,0)+' \u00b7 fiber '+fmtNum(n.fiber,0)+'</small></div></div>':'<div class="hint warn">'+(f.basis==='ml'&&UNIT_G[b.unit]!=null?'this product is labelled by volume; log it in mL, fl oz or servings (no density is known, so grams cannot be derived)':'portion does not resolve to a quantity')+'</div>')+'<div class="btn-row">'+uiBtn('\u2190 Different food','foodsheet.back',null,'btn-ghost btn-sm')+uiBtn(favorites().some(function(x){return x.id===f.id;})?'\u2605 Favorite':'\u2606 Favorite','food.fav',f.kind+'|'+f.id,'btn-ghost btn-sm')+'</div>';}
  return {body:body,foot:'<button class="btn btn-secondary" data-act="edit.close">Cancel</button>'+(F.picked?'<button class="btn btn-secondary" data-act="foodsheet.saveAnother">Log and add another</button><button class="btn btn-primary" data-act="foodsheet.save">Log it</button>':'')};};
function renderFoodSheetResults(){var F=_FOODSHEET;if(!F.q||F.q.length<2){var rec=recentFoods(6);return rec.length?'<div class="card-title" style="font-size:12px;margin:6px 0 2px">Recent</div>'+rec.map(function(f){return foodPickItem(f);}).join(''):'<div class="muted">Type at least two characters.</div>';}var out='';if(F.local.length)out+=F.local.map(function(f){return foodPickItem(f);}).join('');if(F.state==='loading')out+='<div class="muted" style="margin:8px 0">Searching branded products\u2026</div>';else if(F.state==='error')out+='<div class="muted" style="margin:8px 0">Branded database unavailable: '+esc(F.error||'')+'</div>';else if(F.branded.length)out+='<div class="card-title" style="font-size:12px;margin:8px 0 2px">Branded</div>'+F.branded.map(function(f){return foodPickItem(f);}).join('');else if(F.state==='done'&&!F.local.length)out+='<div class="muted">No match. '+uiBtn('Create custom food','food.custom',F.q,'btn-sm btn-secondary')+'</div>';return out;}
function foodPickItem(f){return '<div class="food-item" data-act="foodsheet.pick" data-arg="'+attrEsc(f.kind+'|'+f.id)+'" tabindex="0" role="button"><div><div class="fi-name">'+esc(f.name)+(f.brand?' <span class="muted">'+esc(f.brand)+'</span>':'')+'</div><div class="fi-src">'+esc(f.source)+(f.category?' \u00b7 '+esc(f.category):'')+(f.discontinued?' \u00b7 discontinued':'')+'</div></div><div class="fi-kcal">'+foodKcalLabel(f)+'</div></div>';}
function foodKcalLabel(f){normalizeFood(f);if(f.basis==='serving')return f.perServing&&f.perServing.kcal!=null?fmtNum(f.perServing.kcal,0)+' /serving':'\u2014';var k=f.per100&&f.per100.kcal;return k!=null?fmtNum(k,0)+(f.basis==='ml'?' /100 mL':' /100 g'):'no energy';}
var _foodCatalog={};
function catalogFood(f){_foodCatalog[f.kind+'|'+f.id]=f;return f;}
function foodByRef(ref){if(_foodCatalog[ref])return _foodCatalog[ref];var parts=ref.split('|');var f=localFoods().filter(function(x){return x.kind===parts[0]&&x.id===parts[1];})[0];if(f)return f;var fav=favorites().filter(function(x){return x.kind===parts[0]&&x.id===parts[1];})[0];if(fav)return Object.assign({portions:[]},fav);var rec=recentFoods(50).filter(function(x){return x.kind===parts[0]&&x.id===parts[1];})[0];return rec||null;}
function runFoodSearch(q,target){
  var local=foodSearchLocal(q,20).map(catalogFood);var digits=q.replace(/\D/g,'');var isBarcode=digits.length>=8&&digits.length===q.replace(/\s/g,'').length;
  var set=function(patch){Object.keys(patch).forEach(function(k){target[k]=patch[k];});};
  set({q:q,local:local,branded:[],state:'loading',error:null});
  var seq=(target._seq=(target._seq||0)+1);
  var p=isBarcode?lookupGtin(digits).then(function(f){return f?[f]:[];}):foodSearchBranded(q,40);
  p.then(function(list){if(target._seq!==seq)return;set({branded:list.map(catalogFood),state:'done'});}).catch(function(e){if(target._seq!==seq)return;if(!e||!e.availability)_q(e);set({state:'error',error:e&&e.message||'load failed'});}).then(function(){if(target===_FOODSHEET){var el=document.getElementById('fs_results');if(el)el.innerHTML=renderFoodSheetResults();}else{var el2=document.getElementById('foodResults');if(el2)el2.innerHTML=renderFoodResults(_FOOD_DAY||todayISO());}});
  if(target===_FOODSHEET){var el=document.getElementById('fs_results');if(el)el.innerHTML=renderFoodSheetResults();}else{var el2=document.getElementById('foodResults');if(el2)el2.innerHTML=renderFoodResults(_FOOD_DAY||todayISO());}
}
function saveFoodSheet(opts){var b=_SHEET.buf;var f=normalizeFood(_FOODSHEET.picked);var res=portionResolve(f,b.amount,b.unit);if(!res||!res.qty){toast(f.basis==='ml'?'Log this product in mL, fl oz or servings; grams need a density':'Portion does not resolve to a quantity',{tone:'negative'});return;}var label=res.label;if(b.unit.indexOf('portion:')===0||b.unit==='serving'){label=(num(b.amount)===1?'':fmtNum(num(b.amount),num(b.amount)%1?2:0)+' \u00d7 ')+(b.unit.indexOf('portion:')===0?b.unit.slice(8):'serving')+' ('+_qtyLabel(res.qty,res.basis)+')';}logFood({date:b.date,meal:b.meal,food:f,amount:b.amount,unit:b.unit,portionLabel:label});_memoInvalidate();_FOOD_DAY=b.date;
  if(opts&&opts.another){_FOODSHEET.q='';_FOODSHEET.local=[];_FOODSHEET.branded=[];_FOODSHEET.state='idle';_FOODSHEET.picked=null;renderAll();renderSheet();setTimeout(function(){var q=document.getElementById('fs_q');if(q){q.value='';q.focus();}},30);toast('Logged '+esc(f.name)+'. Search for the next one.',{undo:true});return;}
  closeSheet();renderAll();toast('Logged '+esc(f.name),{undo:true});}
