var _confirmResolve=null,_promptResolve=null;
function confirmDialog(o){return new Promise(function(res){_confirmResolve=res;document.getElementById('confirmTitle').textContent=o.title||'Confirm';document.getElementById('confirmMsg').innerHTML=o.msg||'';var ok=document.getElementById('confirmOk');ok.textContent=o.okLabel||'Continue';ok.className='btn '+(o.danger?'btn-danger':'btn-primary');document.getElementById('confirmBackdrop').classList.add('show');setTimeout(function(){ok.focus();},30);});}
function resolveConfirm(v){document.getElementById('confirmBackdrop').classList.remove('show');if(_confirmResolve){var r=_confirmResolve;_confirmResolve=null;r(v);}}
function promptDialog(o){return new Promise(function(res){_promptResolve=res;document.getElementById('promptTitle').textContent=o.title||'Enter a value';document.getElementById('promptLabel').textContent=o.label||'Value';var inp=document.getElementById('promptInput');inp.value=o.value!=null?o.value:'';inp.type=o.type||'text';if(o.inputmode)inp.setAttribute('inputmode',o.inputmode);document.getElementById('promptBackdrop').classList.add('show');setTimeout(function(){inp.focus();inp.select();},30);});}
function resolvePrompt(v){document.getElementById('promptBackdrop').classList.remove('show');if(_promptResolve){var r=_promptResolve;_promptResolve=null;r(v);}}
/* ---- wake lock while logging ---- */
function requestWakeLock(){try{if(navigator.wakeLock&&navigator.wakeLock.request){navigator.wakeLock.request('screen').then(function(l){_wakeLock=l;}).catch(function(){});}}catch(e){}}
function releaseWakeLock(){try{if(_wakeLock){_wakeLock.release();_wakeLock=null;}}catch(e){}}
/* WATER UNITS: stored in litres, entered and shown in the person's unit */
var WATER_UNITS={ml:{label:'millilitres (ml)',short:'ml',l:0.001},L:{label:'litres (L)',short:'L',l:1},floz:{label:'fluid ounces (fl oz)',short:'fl oz',l:0.0295735},cup:{label:'cups (US, 8 fl oz)',short:'cups',l:0.236588},gal:{label:'gallons (US)',short:'gal',l:3.78541}};
var WATER_QUICK={ml:[250,330,500,750],L:[0.25,0.5,1],floz:[8,12,16,20,32],cup:[1,2],gal:[0.25,0.5]};
function waterUnitDefault(){return DB.settings.waterUnit||(typeof unitPref==='function'&&unitPref()==='metric'?'ml':'floz');}
function toLitres(v,u){if(v==null||!WATER_UNITS[u])return null;return v*WATER_UNITS[u].l;}
function fmtWater(litres){var u=waterUnitDefault();if(litres==null)return '\u2014';var v=litres/WATER_UNITS[u].l;return fmtNum(v,u==='L'||u==='gal'?1:0)+' '+WATER_UNITS[u].short;}
function waterToday(){return obsOf('water').filter(function(o){return o.date===todayISO();}).reduce(function(a,o){return a+(+o.value||0);},0);}
/* context tags in the exact words the models read, each with what it affects */
var CONTEXT_TAGS=[['new scale','starts a new weight baseline: a jump is the scale, not you'],['new tape','starts a new measurement baseline'],['new program','training changes are attributed to the new programme'],
  ['new gym','strength changes may be the equipment'],['travel','weight changes these days are treated as noise'],['illness','weight and strength dips are treated as noise; experiments pause'],
  ['holiday','routine changes are expected; nothing is blamed on the plan'],['alcohol','expect water retention and poorer sleep'],['high sodium','expect a temporary weight rise from water'],
  ['high carb day','expect a temporary weight rise from glycogen and water'],['poor sleep','recovery and hunger are read in that light'],['high stress','recovery and hunger are read in that light'],
  ['injury','training changes are expected; strength drops are not progress signals'],['creatine started','expect 0.5\u20132 kg of water weight over the next weeks'],['medication change','changes from here are flagged as possibly the medication']];
/* objectives to choose from, per phase type (typing one is still possible) */
var PHASE_OBJECTIVES={cut:['Lose fat while keeping strength','Reach a target weight','Get leaner for an event'],bulk:['Gain muscle with as little fat as possible','Increase strength','Reach a target weight'],
  maintenance:['Hold weight and consolidate','Recover after a cut or a gain','Take a diet break'],recomp:['Lose fat and gain muscle at about the same weight','Get stronger at the same weight']};
/* sweat rate from a sweat test: (weight lost + fluid drunk) per hour */
function _sweatRateFrom(b){var pre=num(b.pre),post=num(b.post),m=num(b.minutes),dr=num(b.drank)||0;if(pre==null||post==null||!m||m<10)return null;
  var lostKg=(toCanonicalWeight(pre)-toCanonicalWeight(post))*0.453592,drankL=toLitres(dr,waterUnitDefault())||0,r=(lostKg+drankL)/(m/60);return r>0&&r<4?r:null;}
